<?php if (isset($product)): ?><h6 class="mb-2" data-testid="card-product"><a href="<?= site_url('master/products/' . $product['id']) ?>"><?= e($product['name']) ?></a> <span class="font-monospace text-muted small"><?= e($product['sku']) ?></span></h6><?php endif; ?>
