    <input class="form-control form-control-sm" type="date" name="date_from" value="<?= e($_GET['date_from'] ?? '') ?>"><input class="form-control form-control-sm" type="date" name="date_to" value="<?= e($_GET['date_to'] ?? '') ?>"><button class="btn btn-sm btn-outline-secondary">Filter</button></form></div>
