<?php if (!isset($product)): ?><td class="small"><?= e($r['product_name']) ?><br><span class="text-muted"><?= e($r['sku']) ?></span></td><?php endif; ?><td class="small"><?= e($r['warehouse_name']) ?></td><td class="small font-monospace"><?= e($r['batch_no'] ?? '-') ?><br><span class="text-muted"><?= fmt_date($r['expiry_date']) ?></span></td>
<td class="text-end text-success"><?= $r['qty_in'] > 0 ? fmt_num($r['qty_in'], 0) : '' ?></td><td class="text-end text-danger"><?= $r['qty_out'] > 0 ? fmt_num($r['qty_out'], 0) : '' ?></td><td class="text-end fw-semibold"><?= fmt_num($r['balance_after'], 0) ?></td><td class="text-end small"><?= fmt_idr($r['unit_cost']) ?></td><td class="small"><?= e($r['posted_by_name']) ?></td></tr><?php endforeach; ?>
